// Writes web/ucmicro_gen.go: uc.micro's Unicode classes (Any, Cc, Z, P, S) as
// the regular-expression sources linkify-it builds its patterns from, from
// the uc.micro Node.js WeKan has:
//   node web/testdata/export/generate-ucmicro.mjs /path/to/wekan
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';

const wekan = process.argv[2];
if (!wekan) throw new Error('usage: generate-ucmicro.mjs /path/to/wekan');
const here = path.dirname(new URL(import.meta.url).pathname);
const require = createRequire(path.join(wekan, 'package.json'));
const uc = require('uc.micro');
const version = require('uc.micro/package.json').version;
let out = `// Code generated by testdata/export/generate-ucmicro.mjs from uc.micro ${version}; DO NOT EDIT.\n\npackage web\n\n`;
out += '// ucMicro are uc.micro\'s classes, as JavaScript regular-expression sources\n// over UTF-16 code units.\nvar ucMicro = map[string]string{\n';
for (const k of ['Any', 'Cc', 'Z', 'P', 'S']) {
  // A JSON string is a Go string literal, backslashes and all.
  // Padded as gofmt aligns a map's values.
  out += `\t${JSON.stringify(k)}:${' '.repeat(4 - k.length)}${JSON.stringify(uc[k].source)},\n`;
}
out += '}\n';
fs.writeFileSync(path.join(here, '..', '..', 'ucmicro_gen.go'), out);
